"""Prototype: parallel TF-IDF build + batch search, bit-identical to sequential.py."""

import math
import multiprocessing as mp
import os
import time
from collections import Counter
from heapq import nlargest

from sequential import (
    IndexingResult,
    SearchResult,
    TFIDFIndex,
    compute_term_frequencies,
    search_sequential,
    tokenize,
)


def _tf_chunk(chunk):
    out = []
    for doc_id, text in chunk:
        out.append((doc_id, compute_term_frequencies(tokenize(text))))
    return out


def _lpt_chunks(items, weights, n_chunks):
    order = sorted(range(len(items)), key=lambda i: -weights[i])
    loads = [0] * n_chunks
    bins = [[] for _ in range(n_chunks)]
    for i in order:
        k = min(range(n_chunks), key=loads.__getitem__)
        bins[k].append(i)
        loads[k] += weights[i]
    return [[items[i] for i in sorted(b)] for b in bins if b]


def _ctx():
    try:
        return mp.get_context("fork")
    except ValueError:
        return mp.get_context()


def build_tfidf_index_parallel(documents, num_workers=None, chunk_size=None):
    start = time.perf_counter()
    num_workers = num_workers or os.cpu_count() or 1
    items = [(d.doc_id, d.title + " " + d.content) for d in documents]
    if num_workers > 1 and len(items) > 1:
        weights = [len(t) for _, t in items]
        chunks = _lpt_chunks(items, weights, num_workers * 4)
        with _ctx().Pool(num_workers) as pool:
            parts = pool.map(_tf_chunk, chunks)
        tf_by_id = {}
        for part in parts:
            tf_by_id.update(part)
        doc_term_freqs = {d.doc_id: tf_by_id[d.doc_id] for d in documents}
    else:
        doc_term_freqs = {doc_id: compute_term_frequencies(tokenize(t)) for doc_id, t in items}

    index = TFIDFIndex()
    index.num_documents = len(documents)
    df = Counter()
    for tf in doc_term_freqs.values():
        df.update(tf.keys())
    # sequential iterates a set for vocabulary; dict order of idf/DF follows it — values identical anyway
    index.vocabulary = set(df)
    index.document_frequencies = {t: df[t] for t in index.vocabulary}
    N = index.num_documents
    idf = {t: math.log(N / c) + 1 for t, c in index.document_frequencies.items()}
    index.idf = idf
    postings = {t: [] for t in index.vocabulary}
    for doc_id, tf_dict in doc_term_freqs.items():
        vec = {}
        ns = 0.0
        for term, tf in tf_dict.items():
            w = tf * idf[term]
            vec[term] = w
            ns += w * w
            postings[term].append((doc_id, w))
        index.doc_vectors[doc_id] = vec
        index.doc_norms[doc_id] = math.sqrt(ns)
    for pl in postings.values():
        pl.sort(key=lambda x: x[1], reverse=True)
    index.inverted_index = postings
    return IndexingResult(index=index, elapsed_time=time.perf_counter() - start,
                          num_documents=len(documents), vocabulary_size=len(index.vocabulary))


_G = {}


def _init(index, documents):
    _G["index"] = index
    _G["documents"] = documents


def _search_chunk(args):
    queries, top_k = args
    return [search_sequential(q, _G["index"], top_k, _G["documents"]) for q in queries]


def batch_search_parallel(queries, index, top_k=10, num_workers=None, documents=None):
    num_workers = num_workers or os.cpu_count() or 1
    if num_workers <= 1 or len(queries) < 2:
        return [search_sequential(q, index, top_k, documents) for q in queries]
    n = min(len(queries), num_workers * 4)
    chunks = [(queries[i::n], top_k) for i in range(n)]
    ctx = _ctx()
    if ctx.get_start_method() == "fork":
        _init(index, documents)
        pool = ctx.Pool(num_workers)
    else:
        pool = ctx.Pool(num_workers, initializer=_init, initargs=(index, documents))
    with pool:
        parts = pool.map(_search_chunk, chunks)
    out = [None] * len(queries)
    for i, part in enumerate(parts):
        for j, r in enumerate(part):
            out[i + j * n] = r
    return out

