        return {"limit_mb": os.sysconf("SC_PAGE_SIZE") * os.sysconf("SC_PHYS_PAGES") // (1 << 20), "source": "sysconf"}
    except Exception:  # noqa: BLE001
        return {"limit_mb": None, "source": None}


