"""Sequential log analytics baseline: per-file request stats over a directory of access logs."""
import os, random, re, sys, time
from collections import Counter

LINE = re.compile(r'^(\S+) \S+ \S+ \[[^\]]+\] "(\w+) (\S+) [^"]*" (\d{3}) (\d+)')

def make_logs(folder, n_files=200, seed=7):
    random.seed(seed)
    os.makedirs(folder, exist_ok=True)
    paths = ["/", "/api/items", "/api/users", "/login", "/static/app.js", "/search"]
    for i in range(n_files):
