#!/usr/bin/env python3
"""Parallel log analytics: same result as sequential_stats.analyze_all, computed with a process pool.

Files are packed into size-balanced chunks (LPT on file size, the cost proxy) and the chunks are
handed out dynamically, largest first, so a few huge logs never leave other workers idle.
"""
import heapq
import os
import sys
import time
from collections import Counter
from concurrent.futures import ProcessPoolExecutor

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from sequential_stats import analyze_file  # noqa: E402  (reuse the baseline parser for identical results)

CHUNKS_PER_WORKER = 4
MIN_BYTES_FOR_POOL = 8 << 20  # below ~8 MB of logs, pool start-up costs more than it saves


def _list_files(folder):
    return sorted(os.path.join(folder, f) for f in os.listdir(folder) if f.endswith(".log"))


def _analyze_chunk(chunk):
    """chunk: list of (index, path). Returns ([(index, result), ...], seconds)."""
    t = time.perf_counter()
    out = [(i, analyze_file(p)) for i, p in chunk]
    return out, time.perf_counter() - t


def _lpt_chunks(files, sizes, n_chunks):
    """Longest-processing-time-first packing of files into n_chunks bins, returned heaviest first."""
    order = sorted(range(len(files)), key=lambda i: sizes[i], reverse=True)
    heap = [(0, b) for b in range(n_chunks)]
    bins = [[] for _ in range(n_chunks)]
    loads = [0] * n_chunks
    for i in order:
        load, b = heapq.heappop(heap)
        bins[b].append((i, files[i]))
        loads[b] = load + sizes[i]
        heapq.heappush(heap, (loads[b], b))
    ranked = sorted(range(n_chunks), key=lambda b: loads[b], reverse=True)
    return [bins[b] for b in ranked if bins[b]]


def _merge(per_file):
    total = Counter()
    for r in per_file:
        total.update(r["status"])
    return per_file, dict(total)


def _run(folder, num_workers, collect_times=None):
    files = _list_files(folder)
    if num_workers is None:
        num_workers = os.cpu_count() or 1
    num_workers = max(1, min(int(num_workers), len(files) or 1))
    sizes = [os.path.getsize(p) for p in files]
    if num_workers == 1 or len(files) < 2 or sum(sizes) < MIN_BYTES_FOR_POOL:
        return _merge([analyze_file(p) for p in files])

    chunks = _lpt_chunks(files, sizes, min(len(files), num_workers * CHUNKS_PER_WORKER))
    per_file = [None] * len(files)
    with ProcessPoolExecutor(max_workers=num_workers) as ex:
        # Submit heaviest chunks first; reassemble by index so order matches the baseline.
        for out, secs in ex.map(_analyze_chunk, chunks):
            for i, r in out:
                per_file[i] = r
            if collect_times is not None:
                collect_times.append(secs)
    return _merge(per_file)


def analyze_all_parallel(folder, num_workers=None):
    """Same return value as sequential_stats.analyze_all(folder): (per_file list, status totals dict)."""
    return _run(folder, num_workers)


if __name__ == "__main__":
    folder = sys.argv[1] if len(sys.argv) > 1 else "logs"
    workers = int(sys.argv[2]) if len(sys.argv) > 2 else None
    t = time.perf_counter()
    per_file, total = analyze_all_parallel(folder, workers)
    print(f"{len(per_file)} files in {time.perf_counter()-t:.2f}s; status totals {total}")

